769	// AdminAPIRequest makes an API request according to the CLI flags given,
770	// with the given HTTP method and request URI. If body is non-nil, it will
771	// be assumed to be Content-Type application/json. The caller should close
772	// the response body. Should only be used by Caddy CLI commands which
773	// need to interact with a running instance of Caddy via the admin API.
774	func AdminAPIRequest(adminAddr, method, uri string, headers http.Header, body io.Reader) (*http.Response, error) {
775		parsedAddr, err := caddy.ParseNetworkAddress(adminAddr)
776		if err != nil || parsedAddr.PortRangeSize() > 1 {
777			return nil, fmt.Errorf("invalid admin address %s: %v", adminAddr, err)
778		}
779		origin := "http://" + parsedAddr.JoinHostPort(0)
780		if parsedAddr.IsUnixNetwork() {
781			origin = "http://127.0.0.1" // bogus host is a hack so that http.NewRequest() is happy
782	
783			// the unix address at this point might still contain the optional
784			// unix socket permissions, which are part of the address/host.
785			// those need to be removed first, as they aren't part of the
786			// resulting unix file path
787			addr, _, err := internal.SplitUnixSocketPermissionsBits(parsedAddr.Host)
788			if err != nil {
789				return nil, err
790			}
791			parsedAddr.Host = addr
792		} else if parsedAddr.IsFdNetwork() {
793			origin = "http://127.0.0.1"
794		}
795	
796		// form the request
797		req, err := http.NewRequest(method, origin+uri, body)
798		if err != nil {
799			return nil, fmt.Errorf("making request: %v", err)
800		}
801		if parsedAddr.IsUnixNetwork() || parsedAddr.IsFdNetwork() {
802			// We used to conform to RFC 2616 Section 14.26 which requires
803			// an empty host header when there is no host, as is the case
804			// with unix sockets and socket fds. However, Go required a
805			// Host value so we used a hack of a space character as the host
806			// (it would see the Host was non-empty, then trim the space later).
807			// As of Go 1.20.6 (July 2023), this hack no longer works. See:
808			// https://github.com/golang/go/issues/60374
809			// See also the discussion here:
810			// https://github.com/golang/go/issues/61431
811			//
812			// After that, we now require a Host value of either 127.0.0.1
813			// or ::1 if one is set. Above I choose to use 127.0.0.1. Even
814			// though the value should be completely irrelevant (it could be
815			// "srldkjfsd"), if for some reason the Host *is* used, at least
816			// we can have some reasonable assurance it will stay on the local
817			// machine and that browsers, if they ever allow access to unix
818			// sockets, can still enforce CORS, ensuring it is still coming
819			// from the local machine.
820		} else {
821			req.Header.Set("Origin", origin)
822		}
823		if body != nil {
824			req.Header.Set("Content-Type", "application/json")
825		}
826		maps.Copy(req.Header, headers)
827	
828		// make an HTTP client that dials our network type, since admin
829		// endpoints aren't always TCP, which is what the default transport
830		// expects; reuse is not of particular concern here
831		client := http.Client{
832			Transport: &http.Transport{
833				DialContext: func(_ context.Context, _, _ string) (net.Conn, error) {
834					return net.Dial(parsedAddr.Network, parsedAddr.JoinHostPort(0))
835				},
836			},
837		}
838	
839		resp, err := client.Do(req) //nolint:gosec // the only SSRF here would be self-sabatoge I think
840		if err != nil {
841			return nil, fmt.Errorf("performing request: %v", err)
842		}
843	
844		// if it didn't work, let the user know
845		if resp.StatusCode >= 400 {
846			respBody, err := io.ReadAll(io.LimitReader(resp.Body, 1024*1024*2))
847			if err != nil {
848				return nil, fmt.Errorf("HTTP %d: reading error message: %v", resp.StatusCode, err)
849			}
850			return nil, fmt.Errorf("caddy responded with error: HTTP %d: %s", resp.StatusCode, respBody)
851		}
852	
853		return resp, nil
854	}
855	
856	// DetermineAdminAPIAddress determines which admin API endpoint address should
857	// be used based on the inputs. By priority: if `address` is specified, then
858	// it is returned; if `config` is specified, then that config will be used for
859	// finding the admin address; if `configFile` (and `configAdapter`) are specified,
860	// then that config will be loaded to find the admin address; otherwise, the
861	// default admin listen address will be returned.
862	func DetermineAdminAPIAddress(address string, config []byte, configFile, configAdapter string) (string, error) {
863		// Prefer the address if specified and non-empty
864		if address != "" {
865			return address, nil
866		}
867	
868		// Try to load the config from file if specified, with the given adapter name
869		if configFile != "" {
870			var loadedConfigFile string
871			var err error
872	
873			// use the provided loaded config if non-empty
874			// otherwise, load it from the specified file/adapter
875			loadedConfig := config
876			if len(loadedConfig) == 0 {
877				// get the config in caddy's native format
878				loadedConfig, loadedConfigFile, _, err = LoadConfig(configFile, configAdapter)
879				if err != nil {
880					return "", err
881				}
882				if loadedConfigFile == "" {
883					return "", fmt.Errorf("no config file to load; either use --config flag or ensure Caddyfile exists in current directory")
884				}
885			}
886	
887			// get the address of the admin listener from the config
888			if len(loadedConfig) > 0 {
889				var tmpStruct struct {
890					Admin caddy.AdminConfig `json:"admin"`
891				}
892				err := json.Unmarshal(loadedConfig, &tmpStruct)
893				if err != nil {
894					return "", fmt.Errorf("unmarshaling admin listener address from config: %v", err)
895				}
896				if tmpStruct.Admin.Listen != "" {
897					return tmpStruct.Admin.Listen, nil
898				}
899			}
900		}
901	
902		// Fallback to the default listen address otherwise
903		return caddy.DefaultAdminListen, nil
904	}
905	
906	// configFileWithRespectToDefault returns the filename to use for loading the config, based
907	// on whether a config file is already specified and a supported default config file exists.
908	func configFileWithRespectToDefault(logger *zap.Logger, configFile string) (string, error) {
909		const defaultCaddyfile = "Caddyfile"
910	
911		// if no input file was specified, try a default Caddyfile if the Caddyfile adapter is plugged in
912		if configFile == "" && caddyconfig.GetAdapter("caddyfile") != nil {
913			_, err := os.Stat(defaultCaddyfile)
914			if err == nil {
915				// default Caddyfile exists
916				if logger != nil {
917					logger.Info("using adjacent Caddyfile")
918				}
919				return defaultCaddyfile, nil
920			}
921			if !errors.Is(err, fs.ErrNotExist) {
922				// problem checking
923				return configFile, fmt.Errorf("checking if default Caddyfile exists: %v", err)
924			}
925		}
926	
927		// default config file does not exist or is irrelevant
928		return configFile, nil
929	}
930	
931	type moduleInfo struct {
932		caddyModuleID string
933		goModule      *debug.Module
934		err           error
935	}
936

