package main

import (
	"fmt"
	"net/http"
	"sync"
	"time"
)

var (
	mu       sync.Mutex
	channels []chan struct{}
)

func main() {
	addr := "127.0.0.1:19090"
	if len(osArgs()) > 1 {
		addr = osArgs()[1]
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/hold", func(w http.ResponseWriter, r *http.Request) {
		ch := make(chan struct{})
		mu.Lock()
		channels = append(channels, ch)
		mu.Unlock()
		fmt.Println("upstream: /hold received, blocking")
		select {
		case <-ch:
		case <-r.Context().Done():
			fmt.Println("upstream: /hold client gone")
			return
		}
		w.WriteHeader(200)
		_, _ = w.Write([]byte("held-done"))
	})
	mux.HandleFunc("/five", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(500)
		_, _ = w.Write([]byte("upstream-five-hundred"))
	})
	mux.HandleFunc("/release", func(w http.ResponseWriter, r *http.Request) {
		mu.Lock()
		chans := channels
		channels = nil
		mu.Unlock()
		for _, ch := range chans {
			close(ch)
		}
		w.WriteHeader(200)
		_, _ = w.Write([]byte("released"))
	})
	mux.HandleFunc("/slow", func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(30 * time.Second)
		_, _ = w.Write([]byte("slow-done"))
	})
	fmt.Println("upstream listening on", addr)
	srv := &http.Server{Addr: addr, Handler: mux}
	if err := srv.ListenAndServe(); err != nil {
		panic(err)
	}
}

func osArgs() []string { return getArgs() }

