// keep a reference to admin endpoint singletons while they're active
var (
	serverMu                            sync.Mutex
	localAdminServer, remoteAdminServer *http.Server
	// localAdminListener and remoteAdminListener are the underlying sockets the
	// admin servers Serve on. Keeping them lets exitProcess release the admin
	// listen addresses immediately (before draining in-flight API/app requests)
	// so a replacement process can bind them without waiting.
	localAdminListener, remoteAdminListener net.Listener
	identityCertCache                       *certmagic.Cache
)

// releaseAdminListeners immediately closes the admin endpoint listeners so
// their addresses stop accepting new connections and can be rebound. It does
// not wait for in-flight requests; callers that want a graceful drain should
// also call stopAdminServer on the associated servers afterward.
func releaseAdminListeners() {
	serverMu.Lock()
	lns := []net.Listener{localAdminListener, remoteAdminListener}
	serverMu.Unlock()
	for _, ln := range lns {
		if ln != nil {
			_ = ln.Close()
		}
	}
}

